def preencher_implantacoes_edocs(apps, schema_editor):
    Resultado = apps.get_model(
        "pub_institucional",
        "ResultadoMensalPatriarcaEdocs",
    )
    Implantacao = apps.get_model(
        "pub_institucional",
        "ImplantacaoPatriarcaEdocs",
    )
    Evento = apps.get_model(
        "pub_institucional",
        "EventoAuditoriaImplantacaoEdocs",
    )
    patriarcas_ids = (
        Resultado.objects.filter(coleta__situacao="SUCESSO")
        .filter(
            models.Q(total_processos__gt=0)
            | models.Q(total_documentos__gt=0)
            | models.Q(total_paginas__gt=0)
        )
        .order_by()
        .values_list("patriarca_id", flat=True)
        .distinct()
    )
    for patriarca_id in patriarcas_ids.iterator():
        resultado = (
            Resultado.objects.filter(
                patriarca_id=patriarca_id,
                coleta__situacao="SUCESSO",
            )
            .filter(
                models.Q(total_processos__gt=0)
                | models.Q(total_documentos__gt=0)
                | models.Q(total_paginas__gt=0)
            )
            .select_related("coleta__competencia")
            .order_by(
                "coleta__competencia__ano",
                "coleta__competencia__mes",
                "coleta__revisao",
            )
            .first()
        )
        implantacao, criada = Implantacao.objects.get_or_create(
            patriarca_id=patriarca_id,
            defaults={
                "ano": resultado.coleta.competencia.ano,
                "mes": resultado.coleta.competencia.mes,
                "coleta_evidencia_id": resultado.coleta_id,
                "criterio": "ATIVIDADE_API",
                "totais_evidencia": {
                    "total_processos": resultado.total_processos,
                    "total_documentos": resultado.total_documentos,
                    "total_paginas": resultado.total_paginas,
                },
                "criado_por_nome": "migracao:0011",
                "atualizado_por_nome": "migracao:0011",
            },
        )
        if criada:
            Evento.objects.create(
                implantacao=implantacao,
                mensagem=("Implantação inferida do histórico pela migração 0011."),
                metadados={
                    "coleta_id": str(resultado.coleta_id),
                    "ano": resultado.coleta.competencia.ano,
                    "mes": resultado.coleta.competencia.mes,
                    "criterio": "ATIVIDADE_API",
                },
                criado_por_nome="migracao:0011",
                atualizado_por_nome="migracao:0011",
            )


